/**
 * Custom function to sort an associative array based on 'age' key.
 *
 * @param array $set An associative array where each element is another associative array containing 'name', 'address', and 'age'.
 * @param string $order A string indicating the direction of sorting ('asc' for ascending or 'desc' for descending).
 * @return array The sorted array.
 */
function smart_sort_array($set, $order = 'asc') {
    // Initialize a temporary array to hold the results
    $sorted_set = [];

    foreach ($set as $subArray) {
        if (isset($subArray['age'])) {
            // Add the current sub-array to the sorted set
            $sorted_set[] = $subArray;
        }
    }

    // Sort the sub-arrays in place using the provided order
    usort($sorted_set, function($a, $b) use ($order) {
        if ($order === 'asc') {
            return $a['age'] <=> $b['age'];
        } elseif ($order === 'desc') {
            return $b['age'] <=> $a['age'];
        } else {
            throw new InvalidArgumentException('Invalid order: must be either "asc" or "desc".');
        }
    });

    return $sorted_set;
}

// Example usage:
$people = [
    ['name' => 'Alice', 'address' => '', 'age' => 25],
    ['name' => 'Bob', 'address' => '', 'age' => 30],
    ['name' => 'Charlie', 'address' => '', 'age' => 22]
];

echo json_encode(smart_sort_array($people, 'asc'), JSON_PRETTY_PRINT);
// Output will be:
// [{"name":"Alice","address":"","age":25},{"name":"Bob","address":"","age":30},{"name":"Charlie","address":"","age":22}]

echo json_encode(smart_sort_array($people, 'desc'), JSON_PRETTY_PRINT);
// Output will be:
// [{"name":"Charlie","address":"","age":22},{"name":"Bob","address":"","age":30},{"name":"Alice","address":"","age":25}]
?>
